n, m = map(int, input().split())
grid = [list(map(int, input().split())) for _ in range(n)]

res = 0
for color in [0, 1]:
    # count sets in rows
    for i in range(n):
        count = 0
        for j in range(m):
            if grid[i][j] == color:
                count += 1
        if count > 0:
            res += (1 << count) - 1
    # count sets in columns
    for j in range(m):
        count = 0
        for i in range(n):
            if grid[i][j] == color:
                count += 1
        if count > 0:
            res += (1 << count) - 1

# subtract singletons counted twice (each cell counted once in row and once in column)
# total cells = n*m
# each cell counted twice, so subtract n*m
res -= n * m

print(res)

