MOD = 10**9 + 7

def main():
    import sys
    input = sys.stdin.readline

    N, M = map(int, input().split())
    broken = set(int(input()) for _ in range(M))

    dp = [0] * (N + 1)
    dp[0] = 1

    for i in range(1, N + 1):
        if i in broken:
            dp[i] = 0
        else:
            dp[i] = dp[i-1]
            if i - 2 >= 0:
                dp[i] = (dp[i] + dp[i-2]) % MOD
            else:
                dp[i] %= MOD

    print(dp[N] % MOD)

if __name__ == "__main__":
    main()
